            _ctx.CommandText = _helper.GetRecord();
            _ctx.Add(p_ProposedBudgetID, ProposedBudgetID);
            DataRow row = DaoBase.GetDataRow(_ctx);
            return (row == null) ? null : (ProposedBudgetHd)_helper.DataRowToObject(row, new ProposedBudgetHd());
        }
